style.css:
@-moz-document domain("chat.openai.com") {
body {
    background-color: #ffb5cd !important;
    color: #ffffff !important;
    font-family: "Nunito", sans-serif !important;
  }

  /* Fondo principal del sitio */
  .h-full, .min-h-screen, .flex-1, main, .overflow-hidden {
    background-color: #ffb5cd !important;
    color: #ffffff !important;
  }

  /* Contenedor de los mensajes */
  .group.w-full.text-token-text-primary {
    background-color: #ffc3d4 !important;
    color: #ffffff !important;
    border-radius: 12px !important;
    padding: 1rem !important;
    margin-bottom: 1rem !important;
  }

  /* Área de entrada */
  .sticky.bottom-0, .text-token-text-primary, .px-3 {
    background-color: #ffb5cd !important;
    color: #ffffff !important;
  }

  textarea, input {
    background-color: #fff0f5 !important;
    color: #333 !important;
    border-radius: 8px !important;
    border: none !important;
  }

  textarea::placeholder {
    color: #aa6e83 !important;
  }

  /* Botones */
  button {
    background-color: #ffffff !important;
    color: #ff5b8c !important;
    font-weight: bold !important;
    border-radius: 8px !important;
  }

  button:hover {
    background-color: #ffe0ec !important;
  }

  /* Oculta el fondo negro del modo oscuro si está activo */
  html[class*="dark"] body {
    background-color: #ffb5cd !important;
  }

  /* Ajuste para texto oscuro en botones de navegación */
  .text-sm.text-token-text-secondary {
    color: #fff !important;
  }
}
